package com.coffeeshop.controller;import com.coffeeshop.model.AuditModels.Entry;import com.coffeeshop.service.AuditService;import javafx.application.Platform;import javafx.beans.property.SimpleStringProperty;import javafx.fxml.FXML;import javafx.scene.control.*;import java.time.LocalDate;import java.util.*;import java.util.concurrent.CompletableFuture;public final class AuditController{private final AuditService service;@FXML private TextField searchField;@FXML private DatePicker fromDate,toDate;@FXML private TableView<Entry>auditTable;@FXML private TableColumn<Entry,String>timeColumn,userColumn,actionColumn,entityColumn,detailsColumn;@FXML private TextArea detailArea;@FXML private Label messageLabel;public AuditController(AuditService s){service=Objects.requireNonNull(s);}@FXML private void initialize(){LocalDate now=LocalDate.now();fromDate.setValue(now.minusMonths(1));toDate.setValue(now);timeColumn.setCellValueFactory(v->text(v.getValue().occurredAt().toString().replace('T',' ')));userColumn.setCellValueFactory(v->text(v.getValue().username()==null?"System":v.getValue().username()));actionColumn.setCellValueFactory(v->text(v.getValue().action()));entityColumn.setCellValueFactory(v->text(v.getValue().entityType()+(v.getValue().entityId()==null?"":" #"+v.getValue().entityId())));detailsColumn.setCellValueFactory(v->text(orDash(v.getValue().details())));auditTable.getSelectionModel().selectedItemProperty().addListener((o,a,b)->details(b));refresh();}@FXML private void refresh(){CompletableFuture.supplyAsync(()->service.entries(searchField.getText(),fromDate.getValue(),toDate.getValue())).whenComplete((v,e)->Platform.runLater(()->{if(e!=null){messageLabel.setText(message(e));return;}auditTable.getItems().setAll(v);messageLabel.setText(v.isEmpty()?"No audit entries match the filters.":"");details(auditTable.getSelectionModel().getSelectedItem());}));}private void details(Entry e){if(e==null){detailArea.clear();return;}detailArea.setText("Action: "+e.action()+"\nEntity: "+e.entityType()+(e.entityId()==null?"":" #"+e.entityId())+"\nUser: "+(e.username()==null?"System":e.username())+"\nOccurred: "+e.occurredAt()+"\nReason: "+orDash(e.reason())+"\nDetails: "+orDash(e.details())+"\n\nBefore:\n"+orDash(e.beforeData())+"\n\nAfter:\n"+orDash(e.afterData()));}private static SimpleStringProperty text(String s){return new SimpleStringProperty(s);}private static String orDash(String s){return s==null||s.isBlank()?"-":s;}private static String message(Throwable e){Throwable x=e;while(x.getCause()!=null)x=x.getCause();return x instanceof IllegalArgumentException?x.getMessage():"Unable to load audit history.";}}
